    local function VM_IIlI(d, k, m)
        local R_1OOl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1OOl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1OOl)
    end

    -- Execution Guard
    local F_OO00lI = loadstring(VM_IIlI(B_lI0lO, 35, 5))
    if F_OO00lI then
